```python
import json
from fractions import Fraction

def atom(predicate, *args, negative=False):
    return (predicate, tuple(args), negative)

def opposite(a):
    return (a[0], a[1], not a[2])

animals = {
    "ant", "stork", "dragon", "fish", "mannikin", "liger", "mouse",
    "worm", "chihuahua", "crow", "wolf", "dalmatian", "goat",
    "walrus", "beetle", "cobra", "dinosaur", "llama", "husky"
}

facts = {
    atom("negotiates", "ant", "stork"),
    atom("photograph", "dragon", "fish"),
    atom("hides_cards", "mannikin", "liger"),
    atom("located", "mouse", "Nigeria"),
    atom("neglects", "worm", "chihuahua"),
    atom("surrenders", "crow", "wolf", negative=True),
    atom("trades_piece", "dalmatian", "stork", negative=True),
}

money = {"stork": Fraction(98)}
if "walrus" in money and money["stork"] > money["walrus"]:
    facts.add(atom("more_money", "stork", "walrus"))

# Nigeria is in Africa; this does not supply a hugs antecedent.
if atom("located", "mouse", "Nigeria") in facts:
    facts.add(atom("located", "mouse", "Africa"))

rules = []

def add(name, body, head):
    rules.append((name, tuple(body), head))

add("Rule1", [
    atom("negotiates", "ant", "stork"),
    atom("trades_piece", "dalmatian", "stork", negative=True),
], atom("power_plant", "stork", "goat"))

for animal in sorted(animals):
    add("Rule2", [atom("power_plant", animal, "goat")],
        atom("shouts", "mouse", "beetle", negative=True))

add("Rule3", [atom("more_money", "stork", "walrus")],
    atom("power_plant", "stork", "goat", negative=True))
add("Rule4", [atom("located", "mouse", "Africa")],
    atom("smiles", "mouse", "cobra"))

for animal in sorted(animals):
    add("Rule5", [
        atom("hugs", animal, "dinosaur"),
        atom("smiles", animal, "cobra"),
    ], atom("shouts", animal, "beetle"))

add("Rule6", [atom("musical_instrument", "llama")],
    atom("calls", "llama", "husky"))
add("Rule7", [atom("agriculture", "mouse")],
    atom("smiles", "mouse", "cobra", negative=True))

for animal in sorted(animals):
    add("Rule8", [atom("photograph", animal, "fish")],
        atom("calls", "llama", "husky", negative=True))

preferred = {
    ("Rule3", "Rule1"),
    ("Rule5", "Rule2"),
    ("Rule6", "Rule8"),
    ("Rule7", "Rule4"),
}

known = set(facts)
seen = set()
while True:
    signature = frozenset(known)
    if signature in seen:
        print("UNSUPPORTED")
        break
    seen.add(signature)

    applicable = [
        rule for rule in rules if all(a in known for a in rule[1])
    ]
    accepted = []
    for rule in applicable:
        name, body, head = rule
        rivals = [r for r in applicable if r[2] == opposite(head)]
        if opposite(head) in facts:
            continue
        if any((name, rival[0]) not in preferred for rival in rivals):
            continue
        accepted.append(rule)

    updated = facts | {r[2] for r in accepted}
    if updated == known:
        target = atom("shouts", "mouse", "beetle")
        positive = target in known
        negative = opposite(target) in known
        if positive and negative:
            print("UNSUPPORTED")
            break

        result = (
            "proved" if positive else
            "disproved" if negative else
            "unknown"
        )

        def supporting_rules(goal, visited=None):
            visited = set() if visited is None else visited
            if goal in facts or goal in visited:
                return set()
            visited.add(goal)
            support = set()
            for name, body, head in accepted:
                if head == goal:
                    support.add(name)
                    for antecedent in body:
                        support |= supporting_rules(antecedent, visited)
            return support

        conclusion = target if positive else opposite(target)
        mouse_rule5 = next(
            r for r in rules if r[0] == "Rule5" and r[2] == target
        )
        missing = [
            {"predicate": a[0], "arguments": list(a[1])}
            for a in mouse_rule5[1] if a not in known
        ]
        print(json.dumps({
            "final_answer": result,
            "evidence": {
                "positive_derived": positive,
                "negative_derived": negative,
                "supporting_rules": sorted(supporting_rules(conclusion)),
                "Rule5_missing_antecedents": missing,
                "Rule3_antecedent_established":
                    atom("more_money", "stork", "walrus") in known,
            },
        }, separators=(",", ":")))
        break
    known = updated
